function updateRoomUI(){const room=rooms[currentRoom];document.body.dataset.room=currentRoom;document.documentElement.style.setProperty('--room-accent',room.accent);$('.eyebrow').innerHTML='<span></span>'+room.tag;$('.intro h1').innerHTML=room.headline;$('.intro p').textContent=room.desc;$('.intro .primary').dataset.station='draw';$('.intro .primary').innerHTML='<span class="dice">⚄</span>今天吃什么';$('#room-title').textContent=room.title;$('#room-summary').textContent=roomCopy[currentRoom][1];$('#room-open').dataset.station=room.primary;$('#room-open').textContent=room.action+' ↗';document.querySelectorAll('.dock button').forEach(b=>{const yes=b.dataset.scene===currentRoom;b.classList.toggle('selected',yes);b.setAttribute('aria-current',yes?'page':'false')});}
function disposeRoom(root){if(!root)return;const geometries=new Set(),materials=new Set();root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>materials.add(m))});geometries.forEach(g=>g.dispose());const textures=new Set();materials.forEach(m=>{for(const v of Object.values(m))if(v?.isTexture&&v!==grain&&v!==scene?.environment)textures.add(v);m.dispose()});textures.forEach(t=>t.dispose());root.removeFromParent();}
function prepareRoom(root){root.updateMatrixWorld(true);const containers=[];root.traverse(o=>{if(o.name.startsWith('part_')||o.name.startsWith('rig_'))containers.push(o);if(o.isMesh){o.castShadow=o.receiveShadow=true;o.material.envMapIntensity=.45;if(['grain','pile'].includes(o.material.name))o.castShadow=false;if(o.material.name.startsWith('plush')){o.material.sheen=.45;o.material.sheenColor=new THREE.Color('#eadcf0');o.material.sheenRoughness=.85;}if(o.material.name==='wood'&&!o.material.userData.woodGrain){o.material.userData.woodGrain=true;o.material.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 vTimber;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvTimber=position;');shader.fragmentShader='varying vec3 vTimber;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat timber=sin(vTimber.z*21.0+vTimber.y*24.0+sin(vTimber.x*.8)*1.2+sin(vTimber.x*3.1)*.12); diffuseColor.rgb*=.95+.045*pow(abs(timber),5.0);');};o.material.customProgramCacheKey=()=> 'authored-oak-v1';}}});if(!containers.length)containers.push(...root.children.filter(o=>o.isGroup||o.type==='Object3D'));
for(const group of containers){const buckets=new Map();group.traverse(o=>{if(!o.isMesh||Array.isArray(o.material))return;let owner=o.parent;while(owner&&owner!==group&&!owner.name.startsWith('part_')&&!owner.name.startsWith('rig_'))owner=owner.parent;if(owner!==group)return;if(!buckets.has(o.material.uuid))buckets.set(o.material.uuid,[]);buckets.get(o.material.uuid).push(o)});const inverse=group.matrixWorld.clone().invert();for(const parts of buckets.values()){if(parts.length<2)continue;const gs=parts.map(o=>{const g=o.geometry.clone().applyMatrix4(new THREE.Matrix4().multiplyMatrices(inverse,o.matrixWorld));for(const a of Object.keys(g.attributes))if(!['position','normal','uv'].includes(a))g.deleteAttribute(a);if(!g.attributes.normal)g.computeVertexNormals();if(!g.attributes.uv)g.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(g.attributes.position.count*2),2));if(!g.index)g.setIndex(Array.from({length:g.attributes.position.count},(_,i)=>i));return g});const geometry=mergeGeometries(gs,false);if(geometry){const batch=new THREE.Mesh(geometry,parts[0].material);batch.name=group.name+'_surface';batch.castShadow=!['grain','pile'].includes(batch.material.name);batch.receiveShadow=true;group.add(batch);parts.forEach(o=>{o.removeFromParent();o.geometry.dispose()})}gs.forEach(g=>g.dispose())}}
root.traverse(o=>{if(o.isMesh&&o.material&&!o.material.map&&o.material.roughness>.6){o.material.bumpMap=grain;o.material.bumpScale=o.material.name.startsWith('plush')?.0015:.006;o.material.needsUpdate=true}});return root;}
function rebuildHotspots(){hotspots.length=0;$('#hotspots').replaceChildren();const positions=rooms[currentRoom].positions||Object.fromEntries(Object.entries(stations).filter(([k])=>!['profile','mascot'].includes(k)).map(([k,s])=>[k,s.pos]));for(const[key,pos]of Object.entries(positions)){const b=document.createElement('button');b.className='hotspot';b.dataset.station=key;b.innerHTML='<i>'+stations[key].icon+'</i>'+stations[key].name;b.setAttribute('aria-label','打开'+stations[key].name);$('#hotspots').appendChild(b);hotspots.push({button:b,pos:vec(...pos),key})}}
async function switchRoom(key){if(!rooms[key]||!renderer||key===currentRoom)return;const token=++roomToken;closePanel();$('#scene-transition').hidden=false;$('#transition-name').textContent=rooms[key].title;$('#scene-transition').setAttribute('aria-busy','true');try{const gltf=await new GLTFLoader().loadAsync('/assets/'+rooms[key].model+'.glb');if(token!==roomToken){disposeRoom(gltf.scene);return}disposeRoom(model);model=prepareRoom(gltf.scene);scene.add(model);sceneRevision++;currentRoom=key;updateRoomUI();rebuildHotspots();refreshInspector();controls.minDistance=5.0;moveCamera(defaultCamera(),defaultTarget());renderer.shadowMap.needsUpdate=true;$('#scene').classList.remove('scene-enter');void $('#scene').offsetWidth;$('#scene').classList.add('scene-enter');$('#scene-transition').hidden=true;$('#scene-transition').setAttribute('aria-busy','false');}catch(e){if(token===roomToken){$('#scene-transition').hidden=true;toast('场景暂时没搬好，请再试一次')}console.error(e)}}
function zoomBy(factor){if(!camera)return;tween=null;const offset=camera.position.clone().sub(controls.target);offset.setLength(THREE.MathUtils.clamp(offset.length()*factor,controls.minDistance,controls.maxDistance));camera.position.copy(controls.target).add(offset);controls.update();updateZoom();}
function updateZoom(){if(!controls)return;const value=zoomBase/camera.position.distanceTo(controls.target);$('#zoom-value').textContent=value.toFixed(1)+'×';}

