const storageKey='kaifan-lobby-art-demo:v1';let saved={mode:'3d',meals:[],favorites:[],shopping:[],posts:[],likedPosts:[]};try{saved={...saved,...JSON.parse(localStorage.getItem(storageKey)||'{}')}}catch{}
