function renderSimple(){const keys=['meals','recipes','pantry','draw','community','shopping'];$('#simple-grid').innerHTML=keys.map(k=>`<button class="simple-tile" data-station="${k}"><span>${stations[k].icon}</span><strong>${stations[k].name}</strong><small>${k==='meals'?saved.meals.length+' 餐小记录':k==='pantry'?'看食材，也找做法':k==='draw'?'不纠结，抽一道':'点击打开'}</small></button>`).join('');$('#simple-covers').innerHTML=catalog.slice(0,3).map(r=>`<button data-recipe="${r.id}"><img src="${image(r)}" alt="${esc(r.name)}">${esc(r.name)}</button>`).join('');$('#simple-stats').textContent=saved.meals.length?`在这个小屋，已经记下 ${saved.meals.length} 餐`:'从记下这一餐开始'}
