if(k==='pantry'){html+=`<p class="section-note">这是一份用于空间交互的示例冰箱</p>${[['🥬','小白菜','冷藏 · 1把','优先吃'],['🥚','鸡蛋','冷藏 · 6个','搭配灵感'],['🍅','番茄','冷藏 · 3个','搭配灵感'],['🥛','牛奶','冷藏 · 1盒','看看做法']].map(([e,n,s,t])=>`<div class="stock-row"><span class="stock-dot">${e}</span><div><strong>${n}</strong><small>${s}</small></div><button class="panel-chip" data-ingredient="${n}">${t}</button></div>`).join('')}<button class="panel-primary" data-station="shopping">去采购小篮看看</button>`}
if(k==='draw'){html+=`<div class="chips">${['不限时间','30分钟内','15分钟内'].map((t,i)=>`<button class="panel-chip" data-time="${i===1?30:i===2?15:0}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><p class="section-note">按时间从现有菜谱中随机挑一道</p><div id="draw-result" class="draw-result"><img class="draw-cover" src="/media/brand_monster.png" alt="小怪抱着饭碗"><h3>小怪，今天吃什么？</h3><p>给平常的一天，一点小惊喜</p></div><button class="panel-primary" id="draw-button">抽一道，开饭咯</button>`}
if(k==='community'){html+=`<p class="section-note">美术预览 · 以下为示例分享</p><article class="community-post"><small>示例 · 住在春天里</small><h3>下班后的十五分钟，留给番茄炒蛋</h3><p>一点酸甜，一碗米饭。今天也被这顿热乎饭治愈了。</p></article><article class="community-post"><small>示例 · 不想洗碗的小厨</small><h3>周末，和朋友一起慢慢吃饭</h3><p>用一锅汤，把想说的话煮得暖暖的。</p></article><button class="panel-primary" data-station="meals">先记下我的这一餐</button>`}
if(k==='profile'){html+=`<div style="text-align:center"><img src="/media/brand_monster.png" alt="小怪" width="130"><h3>小怪的两种生活方式</h3></div><div class="mode-choice"><button data-mode="3d" class="${mode==='3d'?'active':''}">3D 小屋</button><button data-mode="simple" class="${mode==='simple'?'active':''}">简洁模式</button></div><p class="section-note">随时切换，Demo里的餐食和喜欢记录相同。</p><h3>喜欢的菜 · ${saved.favorites.length}</h3>${catalog.filter(r=>saved.favorites.includes(r.id)).slice(0,5).map(mini).join('')||'<p class="section-note">点点菜谱旁的小爱心，留住下一餐的灵感。</p>'}`}
