window.demoState={ready:false,frames:0,get mode(){return mode},get revision(){return sceneRevision},get room(){return currentRoom},get cameraDistance(){return camera?.position.distanceTo(controls.target)},get partVisibility(){const p=model?.getObjectByName(selectedPart);let total=0,visible=0;p?.traverse(o=>{if(o.isMesh)total++});p?.traverseVisible(o=>{if(o.isMesh)visible++});return{total,visible}},get selectedPart(){return selectedPart},get isolated(){return isolated},get parts(){return(partManifest[currentRoom]||[]).map(p=>({id:p.id,name:p.name}))},get modelMeshes(){let n=0;model?.traverse(o=>{if(o.isMesh)n++});return n},get stats(){return renderer?{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles,geometries:renderer.info.memory.geometries,textures:renderer.info.memory.textures}:null},stations:Object.keys(stations)};window.demoActions={openPanel,setMode,closePanel,switchRoom,zoomBy,inspectPart,restoreParts};init();

