// Keep semantic component boundaries after draw-call batching, for real close inspection.
function refreshInspector(){selectedPart='';isolated=false;doorClosed=false;doorTween=null;const parts=partManifest[currentRoom]||[];$('#part-select').innerHTML='<option value="">选择部件 · '+parts.length+' 项</option>'+parts.filter(p=>p.station!=='Architecture').map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('');$('#part-detail').textContent='选择一个部件，单独检查结构与材质。';$('#isolate-part').disabled=true;$('#door-toggle').hidden=currentRoom!=='pantry';$('#door-toggle').textContent='合上冰箱门';$('#part-inspector').hidden=true;$('#hotspots').hidden=false;}
function restoreParts(){model?.traverse(o=>{if(!o.isMesh&&o.name.startsWith('part_'))o.visible=true});selectedPart='';isolated=false;$('#part-select').value='';$('#isolate-part').disabled=true;$('#isolate-part').textContent='单独查看';$('#hotspots').hidden=false;controls.minDistance=5;camera.near=.1;camera.updateProjectionMatrix();renderer.shadowMap.needsUpdate=true;}
