$('#inspect-toggle').onclick=()=>{$('#part-inspector').hidden=!$('#part-inspector').hidden;$('#inspect-toggle').setAttribute('aria-expanded',String(!$('#part-inspector').hidden))};$('#part-select').onchange=e=>inspectPart(e.target.value);
$('#isolate-part').onclick=()=>{if(!selectedPart)return;isolated=!isolated;model.traverse(o=>{if(!o.isMesh&&o.name.startsWith('part_')){const selected=model.getObjectByName(selectedPart);let ancestor=o,inside=false;while(ancestor){if(ancestor===selected)inside=true;ancestor=ancestor.parent}let parentOfSelected=selected;while(parentOfSelected&&parentOfSelected!==o)parentOfSelected=parentOfSelected.parent;o.visible=!isolated||inside||parentOfSelected===o;}});$('#isolate-part').textContent=isolated?'显示整景':'单独查看';renderer.shadowMap.needsUpdate=true;};
